/**
 * WebSocketMessage represents a WebSocket message
 */
export interface WebSocketMessage {
  type: MessageType;
  payload: any;
  gameId?: string;
}
/**
 * PlayerConnectPayload contains player connection data
 */
export interface PlayerConnectPayload {
  playerName: string;
  gameId: string;
  playerId?: string; // Optional: used for reconnection
}
/**
 * GameUpdatedPayload contains updated game state
 */
export interface GameUpdatedPayload {
  game: GameDto;
}
/**
 * PlayerConnectedPayload confirms which player a connection now acts as.
 */
export interface PlayerConnectedPayload {
  playerId: string;
  playerName: string;
}
/**
 * ErrorPayload tells a client that one of its requests failed. It is only ever sent to
 * the client that made the request.
 */
export interface ErrorPayload {
  message: string;
  code?: string;
  /**
   * RequestType is the client message type that failed.
   */
  requestType?: MessageType;
  /**
   * CardID, ResolutionID and SelectionID identify what the failed request was about,
   * so the client can restore that part of its UI.
   */
  cardId?: string;
  resolutionId?: string;
  selectionId?: string;
}
/**
 * LogUpdatePayload contains game log entries sent via WebSocket
 */
export interface LogUpdatePayload {
  logs: StateDiffDto[];
  isHistory: boolean;
}
/**
 * PlayerTakeoverPayload contains data for player takeover requests
 */
export interface PlayerTakeoverPayload {
  gameId: string;
  targetPlayerId: string;
}
/**
 * SpectatorConnectPayload contains spectator connection data.
 */
export interface SpectatorConnectPayload {
  spectatorName: string;
  gameId: string;
}
/**
 * SpectatorConnectedPayload confirms which spectator a connection now acts as.
 */
export interface SpectatorConnectedPayload {
  spectatorId: string;
}
/**
 * ChatMessagePayload contains a chat message from a client.
 */
export interface ChatMessagePayload {
  message: string;
}
/**
 * ChatUpdatePayload contains a new chat message broadcast to all clients.
 */
export interface ChatUpdatePayload {
  chatMessage: ChatMessageDto;
}
/**
 * EmoteName is one of the emotes a player or bot can show over their player card.
 */
export type EmoteName = string;
export const EmoteAngry: EmoteName = "angry";
export const EmoteCelebrate: EmoteName = "celebrate";
export const EmoteThinking: EmoteName = "thinking";
export const EmoteApplause: EmoteName = "applause";
export const EmoteShock: EmoteName = "shock";
export const EmoteLaugh: EmoteName = "laugh";
export const EmoteSad: EmoteName = "sad";
export const EmoteCool: EmoteName = "cool";
/**
 * EmoteSendPayload is sent by a client to show an emote.
 */
export interface EmoteSendPayload {
  emote: "angry" | "celebrate" | "thinking" | "applause" | "shock" | "laugh" | "sad" | "cool";
}
/**
 * EmotePayload is broadcast when a player or bot shows an emote.
 */
export interface EmotePayload {
  playerId: string;
  emote: "angry" | "celebrate" | "thinking" | "applause" | "shock" | "laugh" | "sad" | "cool";
}
/**
 * BotThoughtPayload is broadcast when a bot shows a thought bubble or starts or stops typing.
 */
export interface BotThoughtPayload {
  playerId: string;
  text: string;
  typing: boolean;
}
/**
 * BotRetryPayload is sent by the host to retry a failed bot.
 */
export interface BotRetryPayload {
  playerId: string;
}
